type Load<T> = { data: T | null; loading: boolean; error: string | null; reload: () => void };
function useLoad<T>(loader: () => Promise<T>, deps: unknown[]): Load<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [version, setVersion] = useState(0);
  useEffect(() => {
    let active = true;
    setLoading(true); setError(null);
    loader().then((value) => active && setData(value)).catch((reason: unknown) => active && setError(reason instanceof Error ? reason.message : 'Unable to load data')).finally(() => active && setLoading(false));
    return () => { active = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...deps, version]);
  return { data, loading, error, reload: () => setVersion((current) => current + 1) };
}

const formatDate = (date?: string | null) => date ? new Intl.DateTimeFormat('en', { dateStyle: 'medium' }).format(new Date(date)) : 'Not provided';
const formatMoney = (value?: number | null) => typeof value === 'number' ? `₦${value.toLocaleString('en-NG')}` : 'Not provided';
const short = (value?: string | null, length = 10) => value ? `${value.slice(0, length)}${value.length > length ? '…' : ''}` : '—';
const errorMessage = (error: unknown) => error instanceof Error ? error.message : 'Action could not be completed.';

function StatusBadge({ value }: { value?: string | boolean | null }) {
  const label = typeof value === 'boolean' ? value ? 'Active' : 'Inactive' : value || 'Unavailable';
  const tone = ['approved', 'active', 'success', 'paid', 'read', 'resolved', 'replied'].includes(String(value)) ? 'good' : ['rejected', 'failed', 'dismissed', 'suspended', 'paused'].includes(String(value)) ? 'bad' : 'wait';
  return <span data-testid={`status-${String(value || 'unavailable')}`} className={`status-badge status-${tone}`}>{label}</span>;
}

function EmptyState({ title, detail = 'There are no records matching this view.', action }: { title: string; detail?: string; action?: ReactNode }) {
  return <div className="empty-state" data-testid="empty-state"><div className="empty-mark"><Archive size={20} /></div><h3>{title}</h3><p>{detail}</p>{action}</div>;
}
function PageError({ message, retry }: { message: string; retry: () => void }) {
  return <div className="state-card state-error" data-testid="error-state"><AlertTriangle size={20} /><div><strong>Could not load this view</strong><p>{message}</p><button className="button button-quiet" onClick={retry} data-testid="button-retry"><RefreshCw size={14} /> Retry</button></div></div>;
}
function SkeletonTable() {
  return <div className="panel" data-testid="loading-state"><div className="skeleton skeleton-title" />{Array.from({ length: 5 }).map((_, index) => <div className="skeleton skeleton-row" key={index} />)}</div>;
}
function ConfirmButton({ label, onConfirm, danger = false, disabled = false }: { label: string; onConfirm: () => void; danger?: boolean; disabled?: boolean }) {
  return <button disabled={disabled} className={`button ${danger ? 'button-danger' : 'button-quiet'}`} onClick={() => { if (window.confirm(`Confirm: ${label}?`)) onConfirm(); }} data-testid={`button-${label.toLowerCase().replaceAll(' ', '-')}`}><Trash2 size={14} /> {label}</button>;
}

