function ReportDetail({ reportId }: { reportId: string }) {
  const result = useLoad(() => adminApi.reports.get(reportId), [reportId]); const [, setLocation] = useLocation();
  if (result.loading) return <><PageHeader title="Report details" /><SkeletonTable /></>; if (result.error || !result.data) return <PageError message={result.error || 'Report not found'} retry={result.reload} />; const report = result.data;
  const act = async (type: 'resolve' | 'dismiss') => { try { const notes = window.prompt('Admin notes', type === 'resolve' ? 'Reviewed by admin' : 'No policy violation found') || ''; if (type === 'resolve') await adminApi.reports.resolve(report.id, notes); else await adminApi.reports.dismiss(report.id, notes); result.reload(); } catch (error) { window.alert(errorMessage(error)); } };
  return <><button className="back-link" onClick={() => setLocation('/reports')} data-testid="button-back-reports"><ArrowLeft size={15} /> Back to reports</button><PageHeader eyebrow="REPORT INSPECTION" title={report.reason} detail={`Received ${formatDate(report.created_at)}`} action={report.status === 'pending' && <div className="header-actions"><ActionButton primary onClick={() => act('resolve')} testId="button-detail-resolve"><Check size={15} /> Resolve</ActionButton><ActionButton onClick={() => act('dismiss')} testId="button-detail-dismiss"><X size={15} /> Dismiss</ActionButton></div>} /><div className="panel detail-panel"><div className="field-grid"><div><span className="field-label">Status</span><StatusBadge value={report.status} /></div><div><span className="field-label">Reporter</span><strong>{report.reporter?.full_name || report.reporter?.username || 'Unavailable'}</strong><span className="table-secondary">{report.reporter?.email}</span></div><div><span className="field-label">Reported product</span><strong>{report.target_product?.name || 'Not a product report'}</strong></div><div><span className="field-label">Reported user</span><strong>{report.target_user?.full_name || report.target_user?.username || 'Not a user report'}</strong></div></div><div className="long-copy"><span className="field-label">Description</span><p>{report.description || 'No description supplied.'}</p></div>{report.admin_notes && <div className="long-copy"><span className="field-label">Admin notes</span><p>{report.admin_notes}</p></div>}</div></>;
}

function ContactPage() {
  const [status, setStatus] = useState(''); const [search, setSearch] = useState(''); const [page, setPage] = useState(1); const result = useLoad(() => adminApi.contact.list({ status, search, page, limit: 20 }), [status, search, page]); const messages = result.data?.data || [];
  const changeStatus = async (message: ContactMessage, next: ContactMessage['status']) => { try { await adminApi.contact.status(message.id, next); result.reload(); } catch (error) { window.alert(errorMessage(error)); } };
  return <><PageHeader eyebrow="SUPPORT INBOX" title="Contact messages" detail="Read inbound support messages and keep their response status current." /><Toolbar><div className="search-box"><Search size={16} /><Input value={search} onChange={(value) => { setSearch(value); setPage(1); }} placeholder="Search sender, subject or message" testId="input-contact-search" /></div><select className="select" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }} data-testid="select-contact-status"><option value="">All statuses</option><option value="new">New</option><option value="read">Read</option><option value="replied">Replied</option></select></Toolbar>{result.loading ? <SkeletonTable /> : result.error ? <PageError message={result.error} retry={result.reload} /> : !messages.length ? <EmptyState title="Inbox is clear" detail="No contact messages match this view." /> : <div className="panel"><div className="scroll-table"><table className="data-table"><thead><tr><th>Sender</th><th>Subject</th><th>Message</th><th>Status</th><th>Received</th><th>Actions</th></tr></thead><tbody>{messages.map((message) => <tr key={message.id} data-testid={`row-contact-${message.id}`}><td><Link className="table-primary" href={`/contact/${message.id}`}>{message.name}</Link><span className="table-secondary">{message.email}</span></td><td>{message.subject}</td><td>{short(message.message, 50)}</td><td><StatusBadge value={message.status} /></td><td>{formatDate(message.created_at)}</td><td><div className="table-actions"><select className="mini-select" value={message.status} onChange={(event) => changeStatus(message, event.target.value as ContactMessage['status'])} data-testid={`select-contact-status-${message.id}`}><option value="new">New</option><option value="read">Read</option><option value="replied">Replied</option></select><ConfirmButton label="Delete" onConfirm={async () => { try { await adminApi.contact.remove(message.id); result.reload(); } catch (error) { window.alert(errorMessage(error)); } }} danger /></div></td></tr>)}</tbody></table></div><Pagination page={page} totalPages={result.data?.pagination?.totalPages} onChange={setPage} /></div>}</>;
}

function ContactDetail({ messageId }: { messageId: string }) {
  const result = useLoad(() => adminApi.contact.get(messageId), [messageId]); const [, setLocation] = useLocation();
  if (result.loading) return <><PageHeader title="Message details" /><SkeletonTable /></>; if (result.error || !result.data) return <PageError message={result.error || 'Message not found'} retry={result.reload} />; const message = result.data;
  const changeStatus = async (status: ContactMessage['status']) => { try { await adminApi.contact.status(message.id, status); result.reload(); } catch (error) { window.alert(errorMessage(error)); } };
  return <><button className="back-link" onClick={() => setLocation('/contact')} data-testid="button-back-contact"><ArrowLeft size={15} /> Back to contact</button><PageHeader eyebrow="SUPPORT MESSAGE" title={message.subject} detail={`Received ${formatDate(message.created_at)}`} /><div className="panel message-detail"><div className="message-meta"><div className="avatar-large">{message.name.slice(0, 1).toUpperCase()}</div><div><h3>{message.name}</h3><p>{message.email} {message.phone && `· ${message.phone}`}</p></div><StatusBadge value={message.status} /></div><div className="long-copy"><span className="field-label">Message</span><p>{message.message}</p></div><div className="editor-actions"><ActionButton onClick={() => changeStatus('new')} testId="button-message-new">Mark new</ActionButton><ActionButton onClick={() => changeStatus('read')} testId="button-message-read">Mark read</ActionButton><ActionButton primary onClick={() => changeStatus('replied')} testId="button-message-replied">Mark replied</ActionButton></div></div></>;
}

function UnsupportedPage({ title, reason }: { title: string; reason: string }) { return <><PageHeader eyebrow="BACKEND CAPABILITY" title={title} detail="This route is intentionally visible so the boundary is clear." /><div className="unsupported"><Settings size={25} /><h3>Not supported by the current SHINEX API</h3><p>{reason}</p><span>Nothing is stored locally and no unsupported request is made.</span></div></>; }

function UserDetailRoute() { const { id = '' } = useParams<{ id: string }>(); return <AuthGate>{() => <UserDetail userId={id} />}</AuthGate>; }
function ProductDetailRoute() { const { id = '' } = useParams<{ id: string }>(); return <AuthGate>{() => <ProductDetail productId={id} />}</AuthGate>; }
function AdvertisementDetailRoute() { const { id = '' } = useParams<{ id: string }>(); return <AuthGate>{() => <AdvertisementDetail adId={id} />}</AuthGate>; }
function PaymentDetailRoute() { const { id = '' } = useParams<{ id: string }>(); return <AuthGate>{() => <PaymentDetail paymentId={id} />}</AuthGate>; }
function ReportDetailRoute() { const { id = '' } = useParams<{ id: string }>(); return <AuthGate>{() => <ReportDetail reportId={id} />}</AuthGate>; }
function ContactDetailRoute() { const { id = '' } = useParams<{ id: string }>(); return <AuthGate>{() => <ContactDetail messageId={id} />}</AuthGate>; }

function Router() {
  return <ErrorBoundary><Switch>
    <Route path="/login" component={Login} />
    <Route path="/dashboard">{() => <AuthGate>{() => <Dashboard />}</AuthGate>}</Route>
    <Route path="/users">{() => <AuthGate>{() => <UsersPage />}</AuthGate>}</Route>
    <Route path="/users/:id" component={UserDetailRoute} />
    <Route path="/products">{() => <AuthGate>{() => <ProductsPage />}</AuthGate>}</Route>
    <Route path="/products/:id" component={ProductDetailRoute} />
    <Route path="/categories">{() => <AuthGate>{() => <CategoriesPage />}</AuthGate>}</Route>
    <Route path="/advertisements">{() => <AuthGate>{() => <AdvertisementsPage />}</AuthGate>}</Route>
    <Route path="/advertisements/:id" component={AdvertisementDetailRoute} />
    <Route path="/durations">{() => <AuthGate>{() => <DurationsPage />}</AuthGate>}</Route>
    <Route path="/payments">{() => <AuthGate>{() => <PaymentsPage />}</AuthGate>}</Route>
    <Route path="/payments/:id" component={PaymentDetailRoute} />
    <Route path="/reports">{() => <AuthGate>{() => <ReportsPage />}</AuthGate>}</Route>
    <Route path="/reports/:id" component={ReportDetailRoute} />
    <Route path="/contact">{() => <AuthGate>{() => <ContactPage />}</AuthGate>}</Route>
    <Route path="/contact/:id" component={ContactDetailRoute} />
    <Route path="/settings">{() => <AuthGate>{() => <UnsupportedPage title="Settings" reason="The documented backend exposes no admin settings read or write endpoints. Marketplace configuration remains backend-owned." />}</AuthGate>}</Route>
    <Route path="/admin-management">{() => <AuthGate>{() => <UsersPage management />}</AuthGate>}</Route>
    <Route path="/audit-logs">{() => <AuthGate>{() => <UnsupportedPage title="Audit logs" reason="The documented SHINEX admin API does not expose audit log endpoints. This console does not invent an audit trail." />}</AuthGate>}</Route>
    <Route path="/">{() => getToken() ? <Redirect to="/dashboard" /> : <Redirect to="/login" />}</Route>
    <Route component={NotFound} />
  </Switch></ErrorBoundary>;
}

export default function App() {
  return (
    <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}>
      <Router />
    </WouterRouter>
  );
}